css:
/* studio: css module src/components/PlanCard.module.css */
.PlanCard_card__25f1b {
  border: 1px solid #d9d9d9;
  border-radius: 8px;
  padding: 12px;
}

.PlanCard_name__d3b29 {
  font-weight: 600;
}


/* studio: css module src/screens/CanonicalScreen.module.css */
.CanonicalScreen_hero__8aa84 {
  padding: 24px;
}


/* studio: css module src/screens/ESimActivation.module.css */
.ESimActivation_screen__290b3 {
  background-color: var(--color-light);
  max-width: 390px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-family: "Open Sans", sans-serif;
  color: var(--color-metal);
}

/* ── Header ── */
.ESimActivation_header__32c4f {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--color-alice);
}

.ESimActivation_closeLink__63d61 {
  color: var(--color-aqua-100);
  font-size: 17px;
  font-weight: 400;
  min-width: 48px;
  cursor: pointer;
}

.ESimActivation_headerTitle__3d36a {
  font-size: 17px;
  font-weight: 600;
  color: var(--color-metal);
  margin: 0;
  text-align: center;
  flex: 1;
}

.ESimActivation_headerSpacer__55d57 {
  min-width: 48px;
}

/* ── Hero ── */
.ESimActivation_hero__637c5 {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 32px 24px 28px;
  gap: 8px;
}

.ESimActivation_brandIcons__25ab5 {
  display: flex;
  align-items: flex-end;
  margin-bottom: 12px;
}

.ESimActivation_airlineBadge__280f9 {
  border-radius: 50%;
  border: 2px solid var(--color-light);
  z-index: 1;
}

.ESimActivation_checkBadge__c8a39 {
  margin-left: -10px;
  border-radius: 50%;
  border: 2px solid var(--color-light);
  z-index: 2;
}

.ESimActivation_heroTitle__218f8 {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-metal);
  margin: 0;
  text-align: center;
}

.ESimActivation_heroSubtitle__fa33e {
  font-size: 14px;
  color: var(--color-chateau);
  margin: 0;
  text-align: center;
}

.ESimActivation_heroAction__168d9 {
  margin-top: 16px;
  width: 100%;
  display: flex;
  justify-content: center;
}

/* ── Sections ── */
.ESimActivation_section__d8db6 {
  padding: 20px 16px 8px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.ESimActivation_sectionTitle__c3cec {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-metal);
  margin: 0;
}

/* ── Cards ── */
.ESimActivation_card__51026 {
  background-color: var(--color-light);
  border: 1px solid var(--color-gainsboro);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.ESimActivation_cardBadge__645aa {
  display: flex;
}

.ESimActivation_cardRow__86447 {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.ESimActivation_cardEmoji__1221e {
  flex-shrink: 0;
  border-radius: 8px;
}

.ESimActivation_cardText__cf489 {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ESimActivation_cardTitle__da943 {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-metal);
}

.ESimActivation_cardSubtext__d6784 {
  font-size: 13px;
  color: var(--color-chateau);
  margin: 0;
}

.ESimActivation_cardFooter__a3163 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.ESimActivation_cardCode__6aeb4 {
  font-size: 14px;
  color: var(--color-metal);
}

/* ── Add-ons ── */
.ESimActivation_addonRow__856fc {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ESimActivation_simIcon__7bb43 {
  flex-shrink: 0;
  border-radius: 8px;
}

.ESimActivation_addonText__5018f {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ESimActivation_addonTitle__f7fd8 {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-metal);
}

.ESimActivation_addonSubtext__e0c97 {
  font-size: 13px;
  color: var(--color-chateau);
  margin: 0;
}
